AnchorList * /* <=== putAnchor */ 
putAnchor(AnchorList *al, char *url, char *target, Anchor **anchor_return,
	  char *referer, char *title, unsigned char key, int line, int pos)
{
    int n, i, j;
    Anchor *a;
    BufferPoint bp = { 0 };
    if (al == NULL) {
	al = New(AnchorList);
	al->anchors = NULL;
	al->nanchor = al->anchormax = 0;
	al->acache = -1;
    }
    if (al->anchormax == 0) {
	/* first time; allocate anchor buffer */
	al->anchors = New_N(Anchor, FIRST_ANCHOR_SIZE);
	al->anchormax = FIRST_ANCHOR_SIZE;
    }
    if (al->nanchor == al->anchormax) {	/* need realloc */
	al->anchormax *= 2;
	al->anchors = New_Reuse(Anchor, al->anchors, al->anchormax);
    }
    bp.line = line;
    bp.pos = pos;
    n = al->nanchor;
    if (!n || bpcmp(al->anchors[n - 1].start, bp) < 0)
	i = n;
    else
	for (i = 0; i < n; i++) {
	    if (bpcmp(al->anchors[i].start, bp) >= 0) {
		for (j = n; j > i; j--)
		    al->anchors[j] = al->anchors[j - 1];
		break;
	    }
	}
    a = &al->anchors[i];
    a->url = url;
    a->target = target;
    a->referer = referer;
    a->title = title;
    a->accesskey = key;
    a->slave = FALSE;
    a->start = bp;
    a->end = bp;
    al->nanchor++;
    if (anchor_return)
	*anchor_return = a;
    return al;
}

static int /* <=== nextColumn */ 
nextColumn(int n, char *p, Lineprop *pr)
{
    if (*pr & PC_CTRL) {
	if (*p == '\t')
	    return (n + Tabstop) / Tabstop * Tabstop;
	else if (*p == '\n')
	    return n + 1;
	else if (*p != '\r')
	    return n + 2;
	return n;
    }
#ifdef USE_M17N
    if (*pr & PC_UNKNOWN)
	return n + 4;
    return n + wtf_width((wc_uchar *) p);
#else
    return n + 1;
#endif
}

int /* <=== calcPosition */ 
calcPosition(char *l, Lineprop *pr, int len, int pos, int bpos, int mode)
{
    static int *realColumn = NULL;
    static int size = 0;
    static char *prevl = NULL;
    int i, j;

    if (l == NULL || len == 0)
	return bpos;
    if (l == prevl && mode == CP_AUTO) {
	if (pos <= len)
	    return realColumn[pos];
    }
    if (size < len + 1) {
	size = (len + 1 > LINELEN) ? (len + 1) : LINELEN;
	realColumn = New_N(int, size);
    }
    prevl = l;
    i = 0;
    j = bpos;
#ifdef USE_M17N
    if (pr[i] & PC_WCHAR2) {
	for (; i < len && pr[i] & PC_WCHAR2; i++)
	    realColumn[i] = j;
	if (i > 0 && pr[i - 1] & PC_KANJI && WcOption.use_wide)
	    j++;
    }
#endif
    while (1) {
	realColumn[i] = j;
	if (i == len)
	    break;
	j = nextColumn(j, &l[i], &pr[i]);
	i++;
#ifdef USE_M17N
	for (; i < len && pr[i] & PC_WCHAR2; i++)
	    realColumn[i] = realColumn[i - 1];
#endif
    }
    if (pos >= i)
	return j;
    return realColumn[pos];
}

int /* <=== columnPos */ 
columnPos(Line *line, int column)
{
    int i;

    for (i = 1; i < line->len; i++) {
	if (COLPOS(line, i) > column)
	    break;
    }
#ifdef USE_M17N
    for (i--; i > 0 && line->propBuf[i] & PC_WCHAR2; i--) ;
    return i;
#else
    return i - 1;
#endif
}

static inline size_t /* <=== z_mult_no_oflow_ */ 
z_mult_no_oflow_(size_t n, size_t size)
{
	if (size != 0 && n > ULONG_MAX / size) {
		fprintf(stderr,
		    "w3m: overflow in malloc, %lu*%lu\n", (unsigned long)n, (unsigned long)size);
		exit(1);
	}
	return n * size;
}

